// ==========================================
// 2. CORE ENTITY INTERFACES
// ==========================================

export interface BaseEntity {
  id: string;
  createdAt: string;
  updatedAt?: string;
}

export interface TenantEntity extends BaseEntity {
  companyId: string;
}

export interface Company extends BaseEntity {
  name: string;
  commercialRegistration?: string;
  taxNumber?: string;
  phone?: string;
  email?: string;
  address?: string;
  logoUrl?: string;
  currencyDefault: string;
  isActive: boolean;
}

export interface User extends TenantEntity {
  name: string;
  email: string;
  phone?: string;
  role: UserRole;
  isActive: boolean;
  avatarUrl?: string;
  lastLoginAt?: string;
}

export interface ClientContact extends TenantEntity {
  clientId: string;
  name: string;
  title?: string;
  phone?: string;
  mobile?: string;
  email?: string;
  isPrimary: boolean;
  notes?: string;
}

export interface Client extends TenantEntity {
  name: string;
  tradeName?: string;
  taxNumber?: string;
  commercialReg?: string;
  status: ClientStatus;
  salesRepId?: string;
  category?: string; // e.g. "Food Importer", "Chemicals", "Electronics"
  address?: string;
  city?: string;
  country: string;
  notes?: string;
  contacts?: ClientContact[];
}

export interface Port {
  id: string;
  companyId?: string | null; // null = global system port
  code: string; // UN/LOCODE, e.g. EGALY, CNSHA
  nameEn: string;
  nameAr?: string;
  countryCode: string;
  portType: 'sea' | 'air' | 'dry' | 'land';
  isActive: boolean;
}

export interface ShippingLine extends TenantEntity {
  name: string;
  scac?: string; // Standard Carrier Alpha Code (e.g. MSCU, MAEU)
  contactName?: string;
  contactEmail?: string;
  contactPhone?: string;
  website?: string;
  isActive: boolean;
}

export interface OverseasAgent extends TenantEntity {
  name: string;
  countryCode: string;
  city: string;
  contactPerson?: string;
  contactEmail?: string;
  contactPhone?: string;
  specialization?: string;
  isActive: boolean;
}

export interface Vendor extends TenantEntity {
  name: string;
  vendorType: VendorType;
  taxId?: string;
  contactName?: string;
  contactPhone?: string;
  contactEmail?: string;
  isActive: boolean;
}

export interface ChargeItem extends TenantEntity {
  nameEn: string;
  nameAr: string;
  code: string;
  category: 'freight' | 'origin_charges' | 'destination_charges' | 'customs_clearance' | 'inland_haulage' | 'other';
  showInPricing: boolean;
  showInQuotation: boolean;
  showInInvoice: boolean;
  isActive: boolean;
}

export interface QuotationItem extends TenantEntity {
  quotationId: string;
  chargeItemId?: string;
  description: string;
  currency: string;
  costRate: number;
  sellRate: number;
  quantity: number;
  unit: string;
  totalCost: number;
  totalSell: number;
  profit: number;
  profitMarginPercent: number;
  showInClientQuote: boolean;
}

export interface Quotation extends TenantEntity {
  quotationNumber: string;
  clientId: string;
  salesRepId: string;
  originPortId?: string;
  destinationPortId?: string;
  shipmentType: ShipmentType;
  incoterm: Incoterm;
  status: QuotationStatus;
  validUntil: string;
  currency: string;
  totalCost: number;
  totalSell: number;
  totalProfit: number;
  estimatedTransitDays?: number;
  termsAndConditions?: string;
  notes?: string;
  items?: QuotationItem[];
}

export interface ShipmentContainer extends TenantEntity {
  shipmentId: string;
  containerNumber?: string;
  containerType: ContainerType;
  sealNumber?: string;
  tareWeightKg?: number;
  cargoWeightKg?: number;
  status: ContainerStatus;
  notes?: string;
}

export interface ShipmentEvent extends TenantEntity {
  shipmentId: string;
  fromStage?: ShipmentStage;
  toStage: ShipmentStage;
  changedById: string;
  notes?: string;
  location?: string;
  eventAt: string;
}

export interface ShipmentCost extends TenantEntity {
  shipmentId: string;
  vendorId?: string;
  chargeItemId?: string;
  description: string;
  currency: string;
  estimatedCost: number;
  actualCost: number;
  isReconciled: boolean;
  notes?: string;
}

export interface CustomsDossier extends TenantEntity {
  shipmentId: string;
  acidNumber?: string; // Egyptian Advanced Cargo Information Declaration (19 digits)
  acidIssueDate?: string;
  acidExpiryDate?: string;
  customsCertificateNumber?: string; // رقم الشهادة الجمركية / 46
  customsBrokerId?: string;
  customsValueDeclared?: number;
  dutiesPaid?: number;
  vatPaid?: number;
  inspectionDate?: string;
  releaseDate?: string;
  status: 'acid_requested' | 'acid_issued' | 'docs_submitted' | 'assessed' | 'inspected' | 'duties_paid' | 'released';
  notes?: string;
}

export interface Shipment extends TenantEntity {
  jobFileNumber: string; // e.g. BAN-2026-0089
  quotationId?: string;
  clientId: string;
  salesRepId?: string;
  opsOfficerId?: string;
  shippingLineId?: string;
  overseasAgentId?: string;
  shipmentType: ShipmentType;
  incoterm: Incoterm;
  originPortId?: string;
  destinationPortId?: string;
  currentStage: ShipmentStage;
  blNumber?: string;
  vesselName?: string;
  voyageNumber?: string;
  etd?: string;
  eta?: string;
  ata?: string;
  cargoDescription?: string;
  grossWeightKg?: number;
  volumeCbm?: number;
  packageCount?: number;
  packageType?: string;
  containers?: ShipmentContainer[];
  events?: ShipmentEvent[];
  customsDossier?: CustomsDossier;
}

export interface InvoiceItem extends TenantEntity {
  invoiceId: string;
  chargeItemId?: string;
  description: string;
  quantity: number;
  unitPrice: number;
  totalPrice: number;
  currency: string;
}

export interface Invoice extends TenantEntity {
  invoiceNumber: string;
  shipmentId?: string;
  clientId: string;
  invoiceType: InvoiceType;
  status: InvoiceStatus;
  currency: string;
  exchangeRate: number;
  subtotal: number;
  taxAmount: number;
  total: number;
  issueDate?: string;
  dueDate?: string;
  notes?: string;
  createdById?: string;
  items?: InvoiceItem[];
}

export interface CrmActivity extends TenantEntity {
  clientId: string;
  userId: string;
  activityType: ActivityType;
  subject?: string;
  body?: string;
  scheduledAt?: string;
  completedAt?: string;
}

export interface EntityDocument extends TenantEntity {
  entityType: 'shipment' | 'quotation' | 'client' | 'customs_dossier' | 'invoice';
  entityId: string;
  category: DocumentCategory;
  fileName: string;
  fileSize: number;
  mimeType: string;
  storageKey: string; // Cloudflare R2 object path
  publicUrl?: string;
  expiryDate?: string;
  ocrExtractedText?: string;
  uploadedById: string;
}

export interface ScheduledReminder extends TenantEntity {
  title: string;
  entityType?: 'shipment' | 'customs_dossier' | 'quotation' | 'client_contact';
  entityId?: string;
  dueAt: string;
  assignedUserId: string;
  isCompleted: boolean;
  priority: 'low' | 'normal' | 'high' | 'urgent';
}

export interface AuditLog {
  id: number;
  companyId: string;
  userId?: string;
  action: AuditAction;
  tableName: string;
  recordId: string;
  oldData?: Record<string, any>;
  newData?: Record<string, any>;
  ipAddress?: string;
  userAgent?: string;
  createdAt: string;
}

// ==========================================
// 3. API RESPONSE STANDARD SHAPE
// ==========================================

export interface ApiSuccessResponse<T> {
  success: true;
  data: T;
  meta?: {
    page?: number;
    limit?: number;
    total?: number;
    totalPages?: number;
  };
}

export interface ApiErrorResponse {
  success: false;
  error: {
    code: string;
    message: string;
    details?: any[];
    timestamp: string;
    path?: string;
  };
}

export type ApiResponse<T> = ApiSuccessResponse<T> | ApiErrorResponse;

// ==========================================
// 4. MARITIME, PORTS & CURRENCY DOMAIN
// ==========================================

export interface PortDefinition {
  unlocode: string; // e.g., 'EGALY', 'CNSGH'
  name: string;
  nameAr: string;
  country: string;
  countryCode: string; // e.g., 'EG', 'CN'
  flagEmoji: string;
  coordinates: {
    lat: number;
    lng: number;
  };
  portType?: 'sea' | 'dry' | 'land_crossing' | 'air';
  isDryPort?: boolean;
  city?: string;
  region?: string;
  terminals: string[];
  customsAuthorityCode?: string;
  timeZone: string;
}

export interface TradeCorridor {
  id: string;
  code: string;
  nameEn: string;
  nameAr: string;
  type: 'land' | 'multimodal' | 'sea_land';
  originCountry: string;
  destinationCountry: string;
  transitCountries: string[];
  keyBorderCrossings: string[];
  totalDistanceKm: number;
  avgTransitDays: number;
  status: 'active' | 'seasonal' | 'restricted';
  descriptionAr: string;
}

export interface CountryDefinition {
  cca2: string;
  cca3: string;
  nameEn: string;
  nameAr: string;
  capital: string;
  region: string;
  subregion: string;
  currencies: string[];
  callingCode: string;
  latlng: [number, number];
  flagEmoji: string;
}

export interface MaritimeWaypoint {
  name: string;
  lat: number;
  lng: number;
  description?: string;
}

export interface MaritimeRoute {
  id: string;
  originUnlocode: string;
  destinationUnlocode: string;
  nauticalMiles: number;
  standardTransitDays: number;
  waypoints: MaritimeWaypoint[];
}

export interface ContainerIsoValidationResult {
  rawInput: string;
  isValid: boolean;
  ownerCode?: string;
  equipmentCategory?: 'U' | 'J' | 'Z'; // U = Freight Container, J = Detachable freight container-related equipment, Z = Trailers and chassis
  serialNumber?: string;
  checkDigit?: number;
  calculatedCheckDigit?: number;
  errorMessage?: string;
}

export interface CurrencyDefinition {
  code: string; // 'USD', 'EUR', 'EGP', 'AED', 'SAR', 'GBP', 'CNY'
  symbol: string;
  name: string;
  nameAr: string;
  rateToEgp: number;
  rateToUsd: number;
  decimals: number;
  isBase?: boolean;
}

export interface DemurrageTier {
  dayRange: string;
  days: number;
  ratePerDayUsd: number;
  totalUsd: number;
  totalEgp: number;
}

export interface DemurrageCalculationResult {
  containerNumber: string;
  containerType: ContainerType;
  dischargedAt: string;
  gatedOutAt?: string;
  freeDays: number;
  totalDaysInPort: number;
  chargeableDays: number;
  isOverdue: boolean;
  tiers: DemurrageTier[];
  totalDemurrageUsd: number;
  totalDemurrageEgp: number;
  currencyRateApplied: number;
}

